import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { LogOut, Search, User, Check, MapPin, Mail, Phone, X } from 'lucide-react';
import JobCard from '../components/JobCard';

export default function EmployeeDashboard({ user, onLogout, apiUrl }) {
  const [activeTab, setActiveTab] = useState('recommendations');
  const [allJobs, setAllJobs] = useState([]);
  const [appliedJobs, setAppliedJobs] = useState([]);
  const [searchKeyword, setSearchKeyword] = useState('');
  const [showProfileModal, setShowProfileModal] = useState(false);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchJobs();
    fetchAppliedJobs();
  }, []);

  const fetchJobs = async () => {
    try {
      const response = await axios.get(`${apiUrl}/jobs`);
      setAllJobs(response.data);
    } catch (error) {
      console.error('Error fetching jobs:', error);
    }
  };

  const fetchAppliedJobs = async () => {
    try {
      const response = await axios.get(`${apiUrl}/applications/employee/${user.id}`);
      const jobs = response.data.map(app => app.job);
      setAppliedJobs(jobs);
    } catch (error) {
      console.error('Error fetching applied jobs:', error);
    }
  };

  const calculateMatch = (jobKeywords) => {
    const userKeywords = user.profile.keywords.map(k => k.toLowerCase());
    const matchedKeywords = jobKeywords.filter(jk => userKeywords.includes(jk.toLowerCase()));
    return {
      count: matchedKeywords.length,
      percentage: Math.round((matchedKeywords.length / Math.max(jobKeywords.length, 1)) * 100),
      matched: matchedKeywords
    };
  };

  const recommendedJobs = allJobs
    .map(job => ({ ...job, match: calculateMatch(job.keywords) }))
    .sort((a, b) => b.match.count - a.match.count)
    .filter(job => job.match.count > 0);

  const searchResults = allJobs
    .filter(job =>
      job.title.toLowerCase().includes(searchKeyword.toLowerCase()) ||
      job.description.toLowerCase().includes(searchKeyword.toLowerCase()) ||
      job.keywords.some(k => k.toLowerCase().includes(searchKeyword.toLowerCase()))
    )
    .map(job => ({ ...job, match: calculateMatch(job.keywords) }));

  const handleApply = async (jobId) => {
    try {
      await axios.post(`${apiUrl}/applications`, {
        employeeId: user.id,
        jobId
      });
      fetchAppliedJobs();
    } catch (error) {
      console.error('Error applying to job:', error);
    }
  };

  const isApplied = (jobId) => appliedJobs.some(j => j.id === jobId);

  return (
    <div style={{ minHeight: '100vh', background: '#f8f9fa' }}>
      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', color: 'white', padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <h1 style={{ margin: 0, fontSize: '24px', fontWeight: '700' }}>JobMatch</h1>
          <p style={{ margin: '4px 0 0 0', fontSize: '13px', opacity: 0.9 }}>Welcome, {user.profile.name}</p>
        </div>
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
          <button onClick={() => setShowProfileModal(true)} style={{ background: 'rgba(255,255,255,0.2)', color: 'white', border: '1px solid rgba(255,255,255,0.3)', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', fontSize: '14px', fontWeight: '600', display: 'flex', gap: '8px', alignItems: 'center' }}>
            <User size={16} /> Profile
          </button>
          <button onClick={onLogout} style={{ background: 'rgba(255,255,255,0.2)', color: 'white', border: '1px solid rgba(255,255,255,0.3)', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', fontSize: '14px', fontWeight: '600', display: 'flex', gap: '8px', alignItems: 'center' }}>
            <LogOut size={16} /> Logout
          </button>
        </div>
      </div>

      {/* Content */}
      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '30px 20px' }}>
        {/* Tabs */}
        <div style={{ display: 'flex', gap: '10px', marginBottom: '30px', borderBottom: '1px solid #e0e0e0' }}>
          {['recommendations', 'search', 'applied'].map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              style={{
                padding: '12px 20px',
                border: 'none',
                background: activeTab === tab ? '#667eea' : 'transparent',
                color: activeTab === tab ? 'white' : '#666',
                cursor: 'pointer',
                fontSize: '15px',
                fontWeight: '600',
                borderRadius: '8px 8px 0 0'
              }}
            >
              {tab === 'recommendations' && '⭐ Recommended'}
              {tab === 'search' && '🔍 Search'}
              {tab === 'applied' && '✓ Applied'}
            </button>
          ))}
        </div>

        {/* Recommendations */}
        {activeTab === 'recommendations' && (
          <div>
            <h2 style={{ fontSize: '20px', fontWeight: '700', marginBottom: '20px', color: '#1a1a1a' }}>Jobs Recommended For You</h2>
            {recommendedJobs.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {recommendedJobs.map(job => (
                  <JobCard
                    key={job.id}
                    job={job}
                    user={user}
                    onApply={handleApply}
                    isApplied={isApplied(job.id)}
                  />
                ))}
              </div>
            ) : (
              <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px' }}>
                <p style={{ color: '#999', fontSize: '15px' }}>No matching jobs found. Update your profile keywords to see recommendations.</p>
              </div>
            )}
          </div>
        )}

        {/* Search */}
        {activeTab === 'search' && (
          <div>
            <div style={{ marginBottom: '24px', position: 'relative' }}>
              <input
                type="text"
                placeholder="Search by job title, keywords, or company..."
                value={searchKeyword}
                onChange={(e) => setSearchKeyword(e.target.value)}
                style={{
                  width: '100%',
                  padding: '14px 16px 14px 40px',
                  fontSize: '15px',
                  border: '1px solid #e0e0e0',
                  borderRadius: '8px'
                }}
              />
              <Search size={18} style={{ position: 'absolute', left: '14px', top: '14px', color: '#999' }} />
            </div>

            {searchKeyword ? (
              <div>
                <p style={{ color: '#666', marginBottom: '20px', fontSize: '14px' }}>
                  Found {searchResults.length} job{searchResults.length !== 1 ? 's' : ''}
                </p>
                {searchResults.length > 0 ? (
                  <div style={{ display: 'grid', gap: '16px' }}>
                    {searchResults.map(job => (
                      <JobCard
                        key={job.id}
                        job={job}
                        user={user}
                        onApply={handleApply}
                        isApplied={isApplied(job.id)}
                      />
                    ))}
                  </div>
                ) : (
                  <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px' }}>
                    <p style={{ color: '#999', fontSize: '15px' }}>No jobs match your search.</p>
                  </div>
                )}
              </div>
            ) : (
              <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px' }}>
                <p style={{ color: '#999', fontSize: '15px' }}>Start typing to search for jobs...</p>
              </div>
            )}
          </div>
        )}

        {/* Applied */}
        {activeTab === 'applied' && (
          <div>
            <h2 style={{ fontSize: '20px', fontWeight: '700', marginBottom: '20px', color: '#1a1a1a' }}>Your Applications</h2>
            {appliedJobs.length > 0 ? (
              <div style={{ display: 'grid', gap: '16px' }}>
                {appliedJobs.map(job => (
                  <div key={job.id} style={{ background: 'white', padding: '20px', borderRadius: '12px', border: '1px solid #e0e0e0' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', marginBottom: '12px' }}>
                      <div>
                        <h3 style={{ fontSize: '17px', fontWeight: '700', margin: 0, color: '#1a1a1a' }}>{job.title}</h3>
                        <p style={{ fontSize: '13px', color: '#999', margin: '4px 0' }}>Applied {new Date(job.postedDate).toLocaleDateString()}</p>
                      </div>
                      <Check size={20} style={{ color: '#4ade80' }} />
                    </div>
                    <div style={{ display: 'flex', gap: '16px', fontSize: '13px', color: '#666' }}>
                      <span style={{ display: 'flex', gap: '4px', alignItems: 'center' }}><MapPin size={14} /> {job.location}</span>
                      <span>{job.salary}</span>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{ padding: '40px', textAlign: 'center', background: 'white', borderRadius: '12px' }}>
                <p style={{ color: '#999', fontSize: '15px' }}>You haven't applied to any jobs yet.</p>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Profile Modal */}
      {showProfileModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000, padding: '20px' }}>
          <div style={{ background: 'white', borderRadius: '12px', padding: '30px', maxWidth: '500px', width: '100%', maxHeight: '80vh', overflow: 'auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
              <h2 style={{ fontSize: '20px', fontWeight: '700', margin: 0 }}>Your Profile</h2>
              <button onClick={() => setShowProfileModal(false)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>
                <X size={24} />
              </button>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <p style={{ fontSize: '12px', color: '#999', fontWeight: '600', textTransform: 'uppercase', marginBottom: '4px' }}>Name</p>
              <p style={{ fontSize: '15px', fontWeight: '600', margin: 0 }}>{user.profile.name}</p>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <p style={{ fontSize: '12px', color: '#999', fontWeight: '600', textTransform: 'uppercase', marginBottom: '4px' }}>Title</p>
              <p style={{ fontSize: '15px', fontWeight: '600', margin: 0 }}>{user.profile.title}</p>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <p style={{ fontSize: '12px', color: '#999', fontWeight: '600', textTransform: 'uppercase', marginBottom: '4px' }}>Keywords</p>
              <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                {user.profile.keywords.map((kw, i) => (
                  <span key={i} style={{ background: '#f0f0f0', padding: '6px 12px', borderRadius: '20px', fontSize: '13px', fontWeight: '600', color: '#667eea' }}>
                    {kw}
                  </span>
                ))}
              </div>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <p style={{ fontSize: '12px', color: '#999', fontWeight: '600', textTransform: 'uppercase', marginBottom: '4px' }}>Contact</p>
              <p style={{ fontSize: '13px', margin: '4px 0', display: 'flex', gap: '8px', alignItems: 'center' }}>
                <Phone size={14} /> {user.profile.phone}
              </p>
              <p style={{ fontSize: '13px', margin: '4px 0', display: 'flex', gap: '8px', alignItems: 'center' }}>
                <Mail size={14} /> {user.email}
              </p>
              <p style={{ fontSize: '13px', margin: '4px 0', display: 'flex', gap: '8px', alignItems: 'center' }}>
                <MapPin size={14} /> {user.profile.location}
              </p>
            </div>

            <button onClick={() => setShowProfileModal(false)} style={{ width: '100%', padding: '12px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', fontWeight: '600', cursor: 'pointer' }}>
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
